-- =========================================================
-- 데일리민턴 정식 회원 70명 초기 데이터 (실제 모임 가입 명단 반영)
-- name: 이름 / login_id: 소모임 닉네임 / grade: 급수 / joined_at: 가입일자
-- elo_score는 grade_elo_base 테이블의 급수별 초기 기준 점수(S:1800 ~ G:1100)를 반영합니다.
-- =========================================================

ON CONFLICT (login_id) DO UPDATE SET
    name = EXCLUDED.name,
    role = EXCLUDED.role,
    gender = EXCLUDED.gender,
    grade = EXCLUDED.grade,
    elo_score = EXCLUDED.elo_score,
    joined_at = EXCLUDED.joined_at,
    updated_at = now();
